) -> "torch.nn.Module":
    """Prepare and apply rotation transforms to the model.

    For full-model rotation (``layerwise=False``), applies the rotation
    immediately and returns the mutated model. For layer-wise rotation,
    only initialises rotation matrices; actual per-block rotation is
    deferred to :meth:`on_block_ready`.

    This method is idempotent — calling it again after rotation is
    already prepared is a no-op.

    Args:
        model: The model to transform.
        rotation_configs: List of rotation config objects.
        data_type: Quantization data type (e.g. ``"mx_fp"``).
        layerwise: If ``True``, defer rotation to per-block hooks.

    Returns:
        The (possibly mutated) model.
    """
    if self._rotation_prepared:
        return model

    from auto_round.algorithms.transforms import apply_rotation, normalize_rotation_config
    from auto_round.algorithms.transforms.base import BaseRotation

    self._rotation_transforms = []

    if not rotation_configs:
        self._rotation_prepared = True
        return model

    logger.info("Applying Hadamard transform to the model.")
    for rotation_cfg in rotation_configs:
        if layerwise:
            normalised = normalize_rotation_config(rotation_cfg)
            if normalised is None:
                continue
            rotation = BaseRotation.from_config(normalised)
            if rotation.supports_layerwise:
                logger.info(
                    "[Rotation] Layer-wise mode: preparing R matrices only "
                    "(rotation deferred to per-block hook)."
